import sys
sys.path.insert(0, 'python')
from synapse.mcp._tool_registry import TOOL_DEFS

# Count by category
categories = {}
for name, *rest in TOOL_DEFS:
    if name.startswith('houdini_'):
        cat = 'houdini'
    elif name.startswith('synapse_'):
        cat = 'synapse'
    elif name.startswith('tops_'):
        cat = 'tops'
    elif name.startswith('cops_'):
        cat = 'cops'
    else:
        cat = 'other'
    categories[cat] = categories.get(cat, 0) + 1

print('Tools by category:')
for cat in sorted(categories.keys()):
    print(f'  {cat}: {categories[cat]}')
print(f'Total: {len(TOOL_DEFS)}')
